using System.Collections.Generic;
using System.Text;
using Microsoft.CodeAnalysis;
using static Zendiator.SourceGenerator.SymbolUtilities;

namespace Zendiator.SourceGenerator;

internal static partial class SourceEmitter
{
    private static StringBuilder CreateSourceBuilder() => new StringBuilder().AppendLine("""
        // <auto-generated/>
        #nullable enable
        """);

    internal static string Emit(
        INamedTypeSymbol mediator,
        List<Route> routes,
        List<NotificationRoute> notifications,
        List<MultiRoute> multiRoutes,
        List<Route> syncRoutes,
        List<MultiRoute> syncMultiRoutes,
        List<Route> streamRoutes,
        INamedTypeSymbol handlerDefinition,
        INamedTypeSymbol behaviorDefinition,
        INamedTypeSymbol voidHandlerDefinition,
        INamedTypeSymbol voidBehaviorDefinition,
        INamedTypeSymbol notificationHandlerDefinition,
        INamedTypeSymbol syncHandlerDefinition,
        INamedTypeSymbol syncVoidHandlerDefinition,
        INamedTypeSymbol syncBehaviorDefinition,
        INamedTypeSymbol syncVoidBehaviorDefinition,
        INamedTypeSymbol streamHandlerDefinition,
        INamedTypeSymbol streamBehaviorDefinition)
    {
        var ns = mediator.ContainingNamespace.IsGlobalNamespace ? null : mediator.ContainingNamespace.ToDisplayString();
        var prefix = ns == null ? "global::" : "global::" + ns + ".";
        return EmitCore(
            ns,
            prefix,
            Name(mediator),
            routes,
            notifications,
            multiRoutes,
            syncRoutes,
            syncMultiRoutes,
            streamRoutes,
            handlerDefinition,
            behaviorDefinition,
            voidHandlerDefinition,
            voidBehaviorDefinition,
            notificationHandlerDefinition,
            syncHandlerDefinition,
            syncVoidHandlerDefinition,
            syncBehaviorDefinition,
            syncVoidBehaviorDefinition,
            streamHandlerDefinition,
            streamBehaviorDefinition,
            null);
    }

    internal static string EmitAssembly(
        string targetNamespace,
        List<Route> routes,
        List<NotificationRoute> notifications,
        List<MultiRoute> multiRoutes,
        List<Route> syncRoutes,
        List<MultiRoute> syncMultiRoutes,
        List<Route> streamRoutes,
        INamedTypeSymbol handlerDefinition,
        INamedTypeSymbol behaviorDefinition,
        INamedTypeSymbol voidHandlerDefinition,
        INamedTypeSymbol voidBehaviorDefinition,
        INamedTypeSymbol notificationHandlerDefinition,
        INamedTypeSymbol syncHandlerDefinition,
        INamedTypeSymbol syncVoidHandlerDefinition,
        INamedTypeSymbol syncBehaviorDefinition,
        INamedTypeSymbol syncVoidBehaviorDefinition,
        INamedTypeSymbol streamHandlerDefinition,
        INamedTypeSymbol streamBehaviorDefinition,
        DiEmitOptions? di) => EmitCore(
        targetNamespace,
        "global::" + targetNamespace + ".",
        "global::" + targetNamespace + ".Zendiator",
        routes,
        notifications,
        multiRoutes,
        syncRoutes,
        syncMultiRoutes,
        streamRoutes,
        handlerDefinition,
        behaviorDefinition,
        voidHandlerDefinition,
        voidBehaviorDefinition,
        notificationHandlerDefinition,
        syncHandlerDefinition,
        syncVoidHandlerDefinition,
        syncBehaviorDefinition,
        syncVoidBehaviorDefinition,
        streamHandlerDefinition,
        streamBehaviorDefinition,
        di);
    private static string EmitCore(
        string? targetNamespace,
        string prefix,
        string mediatorName,
        List<Route> routes,
        List<NotificationRoute> notifications,
        List<MultiRoute> multiRoutes,
        List<Route> syncRoutes,
        List<MultiRoute> syncMultiRoutes,
        List<Route> streamRoutes,
        INamedTypeSymbol handlerDefinition,
        INamedTypeSymbol behaviorDefinition,
        INamedTypeSymbol voidHandlerDefinition,
        INamedTypeSymbol voidBehaviorDefinition,
        INamedTypeSymbol notificationHandlerDefinition,
        INamedTypeSymbol syncHandlerDefinition,
        INamedTypeSymbol syncVoidHandlerDefinition,
        INamedTypeSymbol syncBehaviorDefinition,
        INamedTypeSymbol syncVoidBehaviorDefinition,
        INamedTypeSymbol streamHandlerDefinition,
        INamedTypeSymbol streamBehaviorDefinition,
        DiEmitOptions? di)
    {
        var b = CreateSourceBuilder();
        b.AppendLine("""using global::Microsoft.Extensions.DependencyInjection;""");
        if (targetNamespace != null)
            b.AppendLine($$"""namespace {{targetNamespace}};""");
        EmitInterface(
            b,
            routes,
            notifications,
            multiRoutes,
            syncRoutes,
            syncMultiRoutes,
            streamRoutes);
        b.AppendLine("""
            /// <summary>Generated mediator with lazily captured dependencies.</summary>
            public sealed partial class Zendiator : IZendiator, global::System.IDisposable
            {
                private readonly global::Zendiator.DependencyInjection.ZendiatorServiceResolver _services;
                /// <summary>Creates a mediator bound to the supplied scope.</summary>
                public Zendiator(global::System.IServiceProvider services)
                {
                    global::System.ArgumentNullException.ThrowIfNull(services);
                    _services = new global::Zendiator.DependencyInjection.ZendiatorServiceResolver(services);
                }
                void global::System.IDisposable.Dispose() => _services.Dispose();
            """);
        EmitRequests(
            b,
            routes,
            handlerDefinition,
            behaviorDefinition,
            voidHandlerDefinition,
            voidBehaviorDefinition);
        EmitNotifications(b, notifications, notificationHandlerDefinition);
        EmitMulti(
            b,
            multiRoutes,
            handlerDefinition,
            behaviorDefinition,
            voidHandlerDefinition,
            voidBehaviorDefinition);
        EmitSyncRoutes(
            b,
            syncRoutes,
            syncHandlerDefinition,
            syncVoidHandlerDefinition,
            syncBehaviorDefinition,
            syncVoidBehaviorDefinition);
        EmitSyncMulti(
            b,
            syncMultiRoutes,
            syncHandlerDefinition,
            syncVoidHandlerDefinition,
            syncBehaviorDefinition,
            syncVoidBehaviorDefinition);
        EmitStreams(b, streamRoutes, streamHandlerDefinition, streamBehaviorDefinition);
        EmitStreamTokenMerge(b, streamRoutes);
        b.AppendLine("""}""");
        EmitRegistration(
            b,
            prefix,
            mediatorName,
            routes,
            notifications,
            multiRoutes,
            syncRoutes,
            syncMultiRoutes,
            streamRoutes,
            di);
        return b.ToString();
    }
}
